def say(message=''):
    print(message, flush=True)


def progress(name, done, total, began):
    elapsed = max(time.monotonic() - began, .001)
    rate = done / elapsed
    if total:
        percent = min(100.0, done / total * 100)
        bars = int(percent / 5)
        remaining = max(0, (total - done) / max(rate, .00001))
        eta = f'{int(remaining // 60)}m {int(remaining % 60):02d}s'
        print(f'\r{name} [{"=" * bars}{"." * (20 - bars)}] {percent:5.1f}%  ETA {eta} ', end='', flush=True)
    else:
        print(f'\r{name} {done / 1048576:.1f} MiB  {rate / 1048576:.1f} MiB/s ', end='', flush=True)


def connection():
    db = sqlite3.connect(str(DB_PATH), timeout=120)
    db.execute('PRAGMA busy_timeout=120000')
    db.execute('PRAGMA journal_mode=DELETE')  # no permanent WAL/SHM project files
    db.execute('PRAGMA temp_store=MEMORY')
    # SQLite itself enforces the 5 GB maximum, even during blob writes.
    page_size = db.execute('PRAGMA page_size').fetchone()[0]
    max_pages = MAX_DB_BYTES // page_size
    applied_pages = db.execute(f'PRAGMA max_page_count={max_pages}').fetchone()[0]
    if applied_pages > max_pages:
        db.close()
        raise RuntimeError(
            'Existing BRAIN.db is already larger than 5 GB. Back it up and '
            'compact it separately; nothing was deleted.'
        )
    db.execute('CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, val TEXT NOT NULL)')
    db.execute('CREATE TABLE IF NOT EXISTS weights (key TEXT PRIMARY KEY, value BLOB NOT NULL)')
    db.execute('CREATE TABLE IF NOT EXISTS models (name TEXT PRIMARY KEY, sha256 TEXT, bytes INTEGER NOT NULL, data BLOB NOT NULL)')
    db.execute('CREATE TABLE IF NOT EXISTS lessons (id INTEGER PRIMARY KEY, prompt TEXT NOT NULL, answer TEXT NOT NULL, origin TEXT NOT NULL, created INTEGER NOT NULL)')
    db.execute('CREATE UNIQUE INDEX IF NOT EXISTS lessons_unique ON lessons(prompt,answer)')
    db.execute('CREATE INDEX IF NOT EXISTS lessons_prompt ON lessons(prompt)')
    db.execute('CREATE TABLE IF NOT EXISTS observations (id INTEGER PRIMARY KEY, session TEXT NOT NULL, turn INTEGER NOT NULL, speaker TEXT NOT NULL, receiver TEXT NOT NULL, replied_to TEXT NOT NULL, message TEXT NOT NULL, created INTEGER NOT NULL)')
    db.execute('CREATE INDEX IF NOT EXISTS obs_session ON observations(session,turn)')
    db.execute('DROP TABLE IF EXISTS nextword')  # remove the retired lookup-based response cache
    db.commit()
    return db


def set_meta(db, key, value):
    db.execute('INSERT OR REPLACE INTO meta(key,val) VALUES (?,?)', (key, str(value)))


def get_meta(db, key, default=None):
    row = db.execute('SELECT val FROM meta WHERE key=?', (key,)).fetchone()
    return row[0] if row else default


def enforce_db_size(db, incoming=0):
    pages = db.execute('PRAGMA page_count').fetchone()[0]
    size = db.execute('PRAGMA page_size').fetchone()[0]
    if pages * size + incoming > MAX_DB_BYTES:
        raise RuntimeError('BRAIN.db would exceed the strict 5 GB limit; training stopped safely.')


def store_lesson(db, question, answer, origin='corpus'):
    question, answer = question.strip()[:1500], answer.strip()[:2500]
    if not question or not answer:
        return
    db.execute('INSERT OR IGNORE INTO lessons(prompt,answer,origin,created) VALUES(?,?,?,?)', (question, answer, origin, int(time.time())))


def _basic_tokenizer(text):
    """Split text into words, numbers and punctuation before subword encoding."""
    return TOKEN_RE.findall(str(text).lower())


def _bpe_encode_piece(piece):
    """Greedy ranked BPE merges over Unicode characters with a word-start marker."""
    symbols = ['▁'] + list(piece)
    if any(symbol not in _BPE_TOKEN_SET for symbol in symbols):
        symbols = [symbol if symbol in _BPE_TOKEN_SET else '<unk>' for symbol in symbols]
    while len(symbols) > 1:
        candidates = [
            (_BPE_MERGE_RANKS[(symbols[i], symbols[i + 1])][0], i,
             _BPE_MERGE_RANKS[(symbols[i], symbols[i + 1])][1])
            for i in range(len(symbols) - 1)
            if (symbols[i], symbols[i + 1]) in _BPE_MERGE_RANKS
        ]
        if not candidates:
            break
        _, index, merged = min(candidates)
        symbols = symbols[:index] + [merged] + symbols[index + 2:]
    return symbols


def tokenizer(text):
    """AXON's learned BPE tokenizer; unknown words decompose into known characters."""
    pieces = _basic_tokenizer(text)
    if not _BPE_READY:
        return pieces
    tokens = []
    for piece in pieces:
        tokens.extend(_bpe_encode_piece(piece))
    return tokens


def _load_bpe_state(db, vocab):
    global _BPE_READY, _BPE_MERGE_RANKS, _BPE_TOKEN_SET
    raw = get_meta(db, 'bpe_merges_json', '[]')
    merges = json.loads(raw)
    _BPE_MERGE_RANKS = {
        (left, right): (rank, merged)
        for rank, (left, right, merged) in enumerate(merges)
    }
    _BPE_TOKEN_SET = set(vocab)
    _BPE_READY = True


def _merge_bpe_sequence(sequence, pair, merged):
    result = []
    index = 0
    while index < len(sequence):
        if (index + 1 < len(sequence)
                and sequence[index] == pair[0]
                and sequence[index + 1] == pair[1]):
            result.append(merged)
            index += 2
        else:
            result.append(sequence[index])
            index += 1
    return tuple(result)


def _train_bpe(db, max_lines=2000):
    """Train BPE merges from saved text; the neural model learns all reply content."""
    word_counts = collections.Counter()
    rows = db.execute(
        "SELECT prompt,answer FROM lessons "
        "WHERE origin IN ('seed','user','teacher','dialogue_quality_v5') "
        "ORDER BY id DESC LIMIT 20000"
    ).fetchall()
    for question, answer in rows:
        for piece in _basic_tokenizer(question + ' ' + answer):
            if piece:
                word_counts[tuple(['▁'] + list(piece))] += 1
    if DATA_PATH.is_file():
        for question, answer in example_lines(max_lines):
            for piece in _basic_tokenizer(question + ' ' + answer):
                if piece:
                    word_counts[tuple(['▁'] + list(piece))] += 1

    if not word_counts:
        word_counts[('▁', 'a')] = 1

    # Include common English and Turkish characters even if the first corpus is small.
    base = {'▁'}
    for sequence in word_counts:
        base.update(sequence)
    base.update(set(string.ascii_lowercase + string.digits + string.punctuation
                    + "çğıöşüâîûéèáãõñİıĞğŞşÖöÜüÇç"))
    sequences = list(word_counts.items())
    merges = []

    say(f'Training BPE tokenizer from {len(sequences):,} unique text pieces...')
    for merge_index in range(BPE_MERGE_LIMIT):
        pair_counts = collections.Counter()
        for sequence, frequency in sequences:
            for pair in zip(sequence, sequence[1:]):
                pair_counts[pair] += frequency
        if not pair_counts:
            break
        pair, frequency = pair_counts.most_common(1)[0]
        if frequency < 2:
            break
        merged = pair[0] + pair[1]
        updated = collections.Counter()
        for sequence, count in sequences:
            updated[_merge_bpe_sequence(sequence, pair, merged)] += count
        sequences = list(updated.items())
        merges.append((pair[0], pair[1], merged))
        base.add(merged)
        if len(SPECIAL) + len(base) >= VOCAB_SIZE:
            break
        if (merge_index + 1) % 250 == 0:
            say(f'BPE merges: {merge_index + 1:,}/{BPE_MERGE_LIMIT:,}')

    vocab = list(SPECIAL) + sorted(base)
    if len(vocab) > VOCAB_SIZE:
        vocab = vocab[:VOCAB_SIZE]
    return vocab, merges



class AdaptiveResources:
    """Cooperative CPU/RAM governor with optional NVIDIA CUDA acceleration.

    This is advisory scheduling, not a guarantee of system responsiveness.
    No extra packages are required for the CPU path. psutil and CuPy are
    detected when already installed; neither is silently downloaded.
    """
    def __init__(self, profile='balanced'):
        self.profile = profile
        self.cores = max(1, os.cpu_count() or 2)
        self.workers = (max(1, self.cores - 1) if profile == 'max' else
                        max(1, min(4, (self.cores - 1) // 2 or 1)))
        self.cpu_percent = None
        self.ram_available = None
        self.ram_total = None
        self.last_sample = 0.0
        self.last_report = 0.0
        self._prev_times = None
        self.psutil = None
        try:
            import psutil
            self.psutil = psutil
            psutil.cpu_percent(interval=None)
        except ImportError:
            pass
        if profile != 'max':
            self._reduce_process_priority()
        # Restrict existing OpenBLAS/MKL pools if threadpoolctl is available;
        # environment variables alone only apply before NumPy is imported.
        try:
            from threadpoolctl import threadpool_limits
            self._thread_limiter = threadpool_limits(limits=self.workers)
        except ImportError:
            self._thread_limiter = None
        self.sample(force=True)

    def _reduce_process_priority(self):
        try:
            if os.name == 'nt':
                handle = ctypes.windll.kernel32.GetCurrentProcess()
                ctypes.windll.kernel32.SetPriorityClass(handle, 0x00004000)
            elif hasattr(os, 'nice'):
                os.nice(8)
        except (AttributeError, OSError, ValueError):
            pass

    def _windows_system_load(self):
        class FILETIME(ctypes.Structure):
            _fields_ = [('low', ctypes.c_uint32), ('high', ctypes.c_uint32)]
            def integer(self):
                return (int(self.high) << 32) | int(self.low)

        class MEMORYSTATUSEX(ctypes.Structure):
            _fields_ = [
                ('length', ctypes.c_uint32), ('memory_load', ctypes.c_uint32),
                ('total_phys', ctypes.c_uint64), ('avail_phys', ctypes.c_uint64),
                ('total_page', ctypes.c_uint64), ('avail_page', ctypes.c_uint64),
                ('total_virtual', ctypes.c_uint64), ('avail_virtual', ctypes.c_uint64),
                ('avail_extended', ctypes.c_uint64),
            ]
        kernel = ctypes.windll.kernel32
        idle, system, user = FILETIME(), FILETIME(), FILETIME()
        if kernel.GetSystemTimes(ctypes.byref(idle), ctypes.byref(system),
                                 ctypes.byref(user)):
            times = (idle.integer(), system.integer() + user.integer())
            if self._prev_times is not None:
                delta_idle = times[0] - self._prev_times[0]
                delta_total = times[1] - self._prev_times[1]
                if delta_total > 0:
                    self.cpu_percent = max(
                        0.0, min(100.0, 100.0 * (1.0 - delta_idle / delta_total))
                    )
            self._prev_times = times
        memory = MEMORYSTATUSEX()
        memory.length = ctypes.sizeof(memory)
        if kernel.GlobalMemoryStatusEx(ctypes.byref(memory)):
            self.ram_total = int(memory.total_phys)
            self.ram_available = int(memory.avail_phys)

    def sample(self, force=False):
        now = time.monotonic()
        if not force and now - self.last_sample < 4.0:
            return
        self.last_sample = now
        try:
            if self.psutil:
                self.cpu_percent = float(self.psutil.cpu_percent(interval=None))
                memory = self.psutil.virtual_memory()
                self.ram_available = int(memory.available)
                self.ram_total = int(memory.total)
            elif os.name == 'nt':
                self._windows_system_load()
            else:
                if hasattr(os, 'getloadavg'):
                    self.cpu_percent = max(0.0, min(
                        100.0, 100.0 * os.getloadavg()[0] / self.cores
                    ))
                if os.path.isfile('/proc/meminfo'):
                    values = {}
                    with open('/proc/meminfo', encoding='utf-8') as f:
                        for line in f:
                            bits = line.split(':', 1)
                            if len(bits) == 2:
                                values[bits[0]] = int(bits[1].strip().split()[0]) * 1024
                    self.ram_total = values.get('MemTotal')
                    self.ram_available = values.get('MemAvailable')
        except (OSError, ValueError, AttributeError):
            pass

    def available_for_training(self):
        self.sample()
        if self.ram_available is None:
            return True
        reserve = (512 * 1024**2 if self.profile == 'max' else
                   max(768 * 1024**2, int((self.ram_total or 0) * 0.10)))
        return self.ram_available > reserve

    def throttle(self):
        """Yield more CPU time when the user's other programs need it."""
        self.sample()
        while not self.available_for_training():
            if time.monotonic() - self.last_report > 20:
                say('Training paused: reserving RAM for other applications...')
                self.last_report = time.monotonic()
            time.sleep(1.0)
            self.sample(force=True)
        if self.profile == 'max':
            return  # explicit full-speed mode; RAM safety pause still applies
        usage = self.cpu_percent
        if usage is not None:
            if usage >= 92.0:
                time.sleep(0.65)
            elif usage >= 78.0:
                time.sleep(0.23)
            elif usage >= 62.0:
                time.sleep(0.08)
        elif self.profile == 'quiet':
            time.sleep(0.12)

    def describe(self):
        self.sample(force=True)
        cpu = '?' if self.cpu_percent is None else f'{self.cpu_percent:.0f}%'
        free = '?' if self.ram_available is None else f'{self.ram_available / 1024**3:.1f} GiB'
        return f'CPU system usage {cpu} | free RAM {free} | BLAS threads {self.workers}'

    def choose_backend(self, requested='auto'):
        """Use CuPy only if installed, CUDA VRAM is free, and GPU is not busy."""
        if requested == 'cpu':
            return None
        try:
            import cupy as cp
            if cp.cuda.runtime.getDeviceCount() < 1:
                raise RuntimeError('no CUDA device')
            free_vram, _ = cp.cuda.runtime.memGetInfo()
            minimum_vram = 1024 * 1024**2 if self.profile == 'max' else 1536 * 1024**2
            if free_vram < minimum_vram:
                raise RuntimeError('not enough free CUDA VRAM')
            # Avoid competing with foreground graphics/apps.
            if self.profile != 'max' and shutil.which('nvidia-smi'):
                query = subprocess.run(
                    ['nvidia-smi', '--query-gpu=utilization.gpu',
                     '--format=csv,noheader,nounits'],
                    text=True, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                    timeout=3, check=False
                )
                if query.returncode == 0:
                    use = int(query.stdout.strip().splitlines()[0].strip())
                    if use >= 55:
                        raise RuntimeError(f'GPU already {use}% busy')
            cp.asarray([1.0], dtype=cp.float32)
            return cp
        except Exception as exc:
            # CuPy can raise a driver-specific CUDA exception even before
            # training starts; a missing/incompatible GPU must never crash
            # the NumPy fallback path.
            if requested == 'gpu':
                say(f'CUDA unavailable or busy ({exc}); safely using NumPy CPU.')
            return None


def _limit_numpy_threads(profile=None):
    """Choose bounded, high-throughput BLAS threading for the selected mode."""
    profile = profile or AXON_PERFORMANCE_PROFILE
    cores = max(1, os.cpu_count() or 2)
    limit = (max(1, cores - 1) if profile == 'max' else
             max(1, min(4, (cores - 1) // 2 or 1)))
    for key in ('OPENBLAS_NUM_THREADS', 'OMP_NUM_THREADS', 'MKL_NUM_THREADS'):
        try:
            existing = int(os.environ.get(key, limit))
        except ValueError:
            existing = limit
        os.environ[key] = str(limit if profile == 'max' else max(1, min(existing, limit)))


def ensure_numpy(profile=None):
    _limit_numpy_threads(profile)
    try:
        import numpy as np
        return np
    except ImportError:
        say('Installing NumPy (no PyTorch needed)...')
        proc = subprocess.run([sys.executable, '-m', 'pip', 'install', '--only-binary=:all:', 'numpy>=1.26'], check=False)
        if proc.returncode:
            raise RuntimeError('NumPy install failed. Choose Python 3.11–3.13 (64-bit) in PyCharm and retry.')
        return importlib.import_module('numpy')


def request(url):
    return urllib.request.Request(url, headers={'User-Agent': USER_AGENT, 'Accept': 'application/octet-stream'})


def download(url, target, limit, label='Download'):
    target = Path(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    part = target.with_suffix(target.suffix + '.partial')
    # Don't resume against URLs whose content/ETag could have changed.
    if part.exists():
        part.unlink()
    began = time.monotonic()
    done = 0
    try:
        with urllib.request.urlopen(request(url), timeout=65) as src:
            size = int(src.headers.get('Content-Length', 0) or 0)
            if size > limit:
                raise RuntimeError(f'{label} too large: {size} > {limit} bytes')
            with part.open('wb') as out:
                last = time.monotonic()
                while True:
                    block = src.read(1024 * 1024)
                    if not block:
                        break
                    done += len(block)
                    if done > limit:
                        raise RuntimeError(f'{label} exceeded byte limit')
                    out.write(block)
                    if time.monotonic() - last >= .3:
                        progress(label, done, size, began)
                        last = time.monotonic()
        if size and done != size:
            raise RuntimeError(f'Incomplete download: got {done} expected {size}')
        part.replace(target)
        progress(label, done, size, began)
        say()
        return done
    except Exception:
        part.unlink(missing_ok=True)
        raise


def cached_valid(db):
    row = db.execute('SELECT bytes FROM models WHERE name=?', ('teacher',)).fetchone()
    return bool(row and GGUF.is_file() and GGUF.stat().st_size == row[0] and get_meta(db, 'teacher_sha') == TEACHER_SHA)


def write_model_to_db(db, filename):
    size = Path(filename).stat().st_size
    if size > MAX_MODEL_BYTES:
        raise RuntimeError('Pretrained model larger than expected')
    enforce_db_size(db, size + 16*1024*1024)
    say('Storing teacher weights inside BRAIN.db...')
    db.execute('DELETE FROM models WHERE name=?', ('teacher',))
    db.execute('INSERT INTO models(name,sha256,bytes,data) VALUES(?,?,?,zeroblob(?))', ('teacher',TEACHER_SHA,size,size))
    rowid = db.execute('SELECT rowid FROM models WHERE name=?', ('teacher',)).fetchone()[0]
    began = time.monotonic()
    with db.blobopen('models','data',rowid,readonly=False) as blob, open(filename,'rb') as src:
        count = 0
        while True:
            piece = src.read(1024*1024)
            if not piece:
                break
            blob.write(piece)
            count += len(piece)
            if count % (16*1024*1024) < len(piece):
                progress('Save teacher',count,size,began)
    progress('Save teacher',size,size,began)
    say()
    set_meta(db,'teacher_sha',TEACHER_SHA)
    db.commit()


def ensure_teacher(db):
    CACHE.mkdir(parents=True, exist_ok=True)
    if cached_valid(db):
        return GGUF
    # A locally cached teacher is acceptable without another copy in SQLite.
    if GGUF.is_file() and GGUF.stat().st_size <= MAX_MODEL_BYTES:
        digest = hashlib.sha256()
        with GGUF.open('rb') as saved:
            for block in iter(lambda: saved.read(4 * 1024 * 1024), b''):
                digest.update(block)
        if digest.hexdigest() == TEACHER_SHA:
            return GGUF
    row = db.execute('SELECT rowid,bytes,sha256 FROM models WHERE name=?', ('teacher',)).fetchone()
    if row and row[2] == TEACHER_SHA:
        say('Restoring teacher from BRAIN.db to system cache...')
        with db.blobopen('models','data',row[0],readonly=True) as src, GGUF.open('wb') as dst:
            sha = hashlib.sha256()
            while True:
                data = src.read(1024*1024)
                if not data:
                    break
                sha.update(data)
                dst.write(data)
        if sha.hexdigest() != TEACHER_SHA:
            GGUF.unlink(missing_ok=True)
            raise RuntimeError('Stored GGUF SHA256 mismatch; database may be corrupted')
        return GGUF
    say('Downloading Qwen2.5-0.5B-Instruct (about 491 MB, first run only)...')
    download(TEACHER_URL, GGUF, MAX_MODEL_BYTES, 'Qwen teacher')
    sha = hashlib.sha256()
    with GGUF.open('rb') as src:
        for chunk in iter(lambda:src.read(4*1024*1024),b''):
            sha.update(chunk)
    if sha.hexdigest() != TEACHER_SHA:
        GGUF.unlink(missing_ok=True)
        raise RuntimeError('Downloaded GGUF SHA256 mismatch. Check internet connection and retry.')
    # Do not duplicate this ~0.5 GB teacher in BRAIN.db under the 5 GB cap.
    # The separate local cache is reused. Existing stored teacher blobs stay
    # untouched for users who already have them.
    set_meta(db, 'teacher_cache_sha', TEACHER_SHA)
    db.commit()
    say('Optional local teacher stays in the cache; BRAIN.db only stores AXON learning.')
    return GGUF


def server_binary():
    CACHE.mkdir(parents=True,exist_ok=True)
    suffix = '.exe' if os.name == 'nt' else ''
    found = list(CACHE.rglob('llama-server'+suffix))
    if found:
        return found[0]
    system = platform.system().lower()
    machine = platform.machine().lower()
    if system == 'windows' and machine in ('amd64','x86_64'):
        preferred = ('bin-win-cpu-x64.zip',)
    elif system == 'linux' and machine in ('x86_64','amd64'):
        preferred = ('bin-ubuntu-x64.tar.gz',)
    elif system == 'darwin':
        preferred = ('bin-macos-arm64.tar.gz',) if machine == 'arm64' else ('bin-macos-x64.tar.gz',)
    else:
        raise RuntimeError('Auto runtime supports Windows x64, Ubuntu x64, macOS arm64/x64; unsupported platform.')
    say('Installing official llama.cpp CPU runtime into user cache (not project folder)...')
    api = 'https://api.github.com/repos/ggml-org/llama.cpp/releases?per_page=16'
    req = urllib.request.Request(api,headers={'User-Agent': USER_AGENT, 'Accept': 'application/vnd.github+json'})
    with urllib.request.urlopen(req,timeout=30) as src:
        releases = json.load(src)
    assets = [(a['name'],a['browser_download_url']) for release in releases for a in release.get('assets',[])]
    match = next(((n,u) for n,u in assets if any(n.endswith(w) for w in preferred)),None)
    if not match:
        raise RuntimeError('Cannot find an official CPU llama.cpp release. Visit https://github.com/ggml-org/llama.cpp/releases')
    name,url = match
    archive = CACHE / name
    download(url,archive,250*1024*1024,'llama.cpp runtime')
    destination = CACHE / 'runtime'
    destination.mkdir(exist_ok=True)
    # Extract only normal files and defend against traversal.
    def safe_write(member_name, fileobj):
        path = (destination / member_name).resolve()
        if not path.is_relative_to(destination.resolve()):
            raise RuntimeError('Unsafe llama.cpp archive path')
        path.parent.mkdir(parents=True,exist_ok=True)
        with path.open('wb') as out:
            shutil.copyfileobj(fileobj,out)
    if archive.name.endswith('.zip'):
        with zipfile.ZipFile(archive) as z:
            for info in z.infolist():
                if not info.is_dir():
                    if info.file_size > 250*1024*1024: raise RuntimeError('Unexpected runtime file size')
                    with z.open(info) as inp: safe_write(info.filename,inp)
    else:
        with tarfile.open(archive,'r:gz') as t:
            for member in t:
                if member.isfile():
                    if member.size > 250*1024*1024: raise RuntimeError('Unexpected runtime file size')
                    with t.extractfile(member) as inp: safe_write(member.name,inp)
    archive.unlink(missing_ok=True)
    found=list(destination.rglob('llama-server'+suffix))
    if not found:
        raise RuntimeError('llama-server missing from official llama.cpp archive')
    server=found[0]
    if os.name != 'nt': server.chmod(server.stat().st_mode | 0o111)
    return server


class Teacher:
    def __init__(self, model, parallel=4, role="Teacher", resources=None):
        self.model = model
        self.resources = resources
        self.role = role
        self.parallel = max(1, min(12, int(parallel)))
        self.proc = None
        self.port = None
        self.log = None

    def __enter__(self):
        exe = server_binary()
        with socket.socket(socket.AF_INET,socket.SOCK_STREAM) as s:
            s.bind(('127.0.0.1',0))
            self.port = s.getsockname()[1]
        self.log = tempfile.TemporaryFile(mode='w+b')
        helper_threads = (
            self.resources.workers if self.resources is not None and
            self.resources.profile == 'max'
            else max(1, min(4, (os.cpu_count() or 4)//2))
        )
        args=[str(exe), '-m',str(self.model),'--host','127.0.0.1','--port',str(self.port),
              '-c',str(self.parallel*2048),'-np',str(self.parallel),'-cb',
              '-t',str(helper_threads),'-ngl','0']
        say(f'Starting local {self.role} model (CPU, {self.parallel} parallel slots)...')
        self.proc=subprocess.Popen(args,stdout=self.log,stderr=subprocess.STDOUT,cwd=str(exe.parent))
        limit=time.monotonic()+150
        while time.monotonic()<limit:
            if self.proc.poll() is not None:
                break
            try:
                with urllib.request.urlopen(f'http://127.0.0.1:{self.port}/health',timeout=1) as res:
                    if res.status==200:
                        say(f'{self.role} model ready.')
                        return self
            except (OSError,urllib.error.URLError):
                time.sleep(.5)
        self.log.seek(0)
        logs=self.log.read()[-3000:].decode('utf-8','replace')
        self.__exit__(None,None,None)
        raise RuntimeError('Could not start llama-server. Logs:\n'+logs)

    def complete(self, messages, max_tokens=180, stream=False, temperature=.6):
        if self.resources is not None:
            self.resources.throttle()
        payload={'model':'local','messages':messages,'max_tokens':max_tokens,
                 'temperature':temperature,'stream':stream, 'top_p':0.9, 'repeat_penalty':1.12, 'frequency_penalty':0.15}
        req=urllib.request.Request(f'http://127.0.0.1:{self.port}/v1/chat/completions',
            headers={'Content-Type':'application/json'},data=json.dumps(payload).encode())
        with urllib.request.urlopen(req,timeout=300) as response:
            if not stream:
                return json.load(response)['choices'][0]['message']['content']
            chunks=[]
            for raw in response:
                if not raw.startswith(b'data: '):
                    continue
                data=raw[6:].strip()
                if data==b'[DONE]': break
                try:
                    delta=json.loads(data)['choices'][0].get('delta',{})
                    part=delta.get('content') or ''
                except (ValueError,KeyError,IndexError):
                    part=''
                if part:
                    print(part,end='',flush=True)
                    chunks.append(part)
            say()
            return ''.join(chunks)

    def __exit__(self,*args):
        if self.proc:
            self.proc.terminate()
            try: self.proc.wait(timeout=6)
            except subprocess.TimeoutExpired: self.proc.kill()
        if self.log: self.log.close()


def example_lines(lines_limit=None):
    with DATA_PATH.open('r',encoding='utf-8',errors='replace') as file:
        for index,line in enumerate(file):
            if lines_limit is not None and index >= lines_limit: break
            try:
                q,a=line.rstrip('\r\n').split('\t',1)
                if q and a:
                    yield q,a
            except ValueError:
                continue


