def migrate_dialogue_schema(db):
    """Exclude random old Messenger/Receiver lessons from future training.

    Old notes remain preserved. On first upgrade, token weights are archived
    by build_vocabulary's student-architecture migration before new training.
    """
    if get_meta(db, 'human_assistant_migration') == '1' and get_meta(db, 'quality_gate_v5') == '1':
        return
    old = db.execute("SELECT COUNT(*) FROM lessons WHERE origin='dialogue'").fetchone()[0]
    if old:
        say(f'Archiving {old:,} previous random agent-to-agent examples (not training on them).')
        db.execute("UPDATE lessons SET origin='legacy_dialogue' WHERE origin='dialogue'")
    db.execute("DELETE FROM meta WHERE key='ngrams_ready'")
    set_meta(db, 'human_assistant_migration', '1')
    set_meta(db, 'quality_gate_v5', '1')
    db.commit()


def bootstrap_lessons(db):
    """Keep training examples; no lookup-based or n-gram response system is used."""
    migrate_dialogue_schema(db)
    if get_meta(db, 'seed_version') == '3':
        return
    for question, answer in SEED_PAIRS:
        store_lesson(db, question, answer, 'seed')
    set_meta(db, 'seed_version', '3')
    db.commit()


def build_vocabulary(db, max_lines=2000):
    """Build and persist a learned BPE vocabulary and its merge ranks."""
    global _BPE_READY
    if get_meta(db, 'student_arch') != STUDENT_ARCH:
        old_vocab = get_meta(db, 'vocab_json')
        if old_vocab:
            set_meta(db, 'legacy_word_vocab_json', old_vocab)
        if db.execute("SELECT 1 FROM weights WHERE key='emb_in'").fetchone():
            say('Preserving legacy embedding checkpoints in BRAIN.db...')
            enforce_db_size(db, 160 * 1024 * 1024)
            for key in ('emb_in', 'emb_out'):
                db.execute(
                    "INSERT OR IGNORE INTO weights(key,value) "
                    "SELECT ?,value FROM weights WHERE key=?",
                    ('legacy_v5_' + key, key)
                )
        db.execute("DELETE FROM weights WHERE key IN ('emb_in','emb_out')")
        db.execute(
            "DELETE FROM meta WHERE key IN "
            "('vocab_json','student_steps','bpe_merges_json','tokenizer_version',"
            "'transformer_steps','transformer_version','transformer_config','transformer_validation_loss')"
        )
        set_meta(db, 'student_arch', STUDENT_ARCH)
        db.commit()

    cached = get_meta(db, 'vocab_json')
    tokenizer_version = get_meta(db, 'tokenizer_version')
    merges_json = get_meta(db, 'bpe_merges_json')
    if cached and tokenizer_version == BPE_VERSION and merges_json:
        vocab = json.loads(cached)
        _load_bpe_state(db, vocab)
        return vocab

    bootstrap_lessons(db)
    say("Building AXON's learned BPE subword tokenizer...")
    vocab, merges = _train_bpe(db, max_lines=max_lines)
    set_meta(db, 'vocab_json', json.dumps(vocab, ensure_ascii=False))
    set_meta(db, 'bpe_merges_json', json.dumps(merges, ensure_ascii=False))
    set_meta(db, 'tokenizer_version', BPE_VERSION)
    db.commit()
    _load_bpe_state(db, vocab)
    say(
        f'BPE vocabulary: {len(vocab):,}/{VOCAB_SIZE:,} tokens | '
        f'{len(merges):,} learned merges | Unicode character fallback enabled.'
    )
    return vocab


def extend_vocabulary(db, text):
    """Add unseen Unicode characters without changing existing BPE merge ranks."""
    global _BPE_TOKEN_SET
    vocab = build_vocabulary(db)
    seen = set(vocab)
    added = []
    for piece in _basic_tokenizer(text):
        for character in piece:
            if character not in seen and len(vocab) < VOCAB_SIZE:
                seen.add(character)
                vocab.append(character)
                added.append(character)
    if added:
        set_meta(db, 'vocab_json', json.dumps(vocab, ensure_ascii=False))
        db.commit()
        _BPE_TOKEN_SET = set(vocab)
    return vocab


def note_exchange(db, session, turn, speaker, receiver, replied_to, message):
    """Save a transcript as training data; never retrieve it as a chat response."""
    enforce_db_size(db, 8 * 1024 * 1024)
    db.execute(
        'INSERT INTO observations (session,turn,speaker,receiver,replied_to,message,created) '
        'VALUES (?,?,?,?,?,?,?)',
        (session, turn, speaker, receiver, replied_to[:2500], message[:2500], int(time.time()))
    )
    if speaker == 'Assistant' and receiver == 'Human' and replied_to.strip():
        store_lesson(db, replied_to, message, 'dialogue_quality_v5')
    extend_vocabulary(db, replied_to + ' ' + message)
    db.commit()


