def _sequence(q, a, lookup):
    prompt = [3] + [lookup.get(w,1) for w in tokenizer(q)] + [4]
    answer = [lookup.get(w,1) for w in tokenizer(a)] + [2]
    return prompt, answer


def _context(prefix):
    """Keep the current HUMAN question visible as the answer grows.

    The old window lost the user question after 16 generated tokens, making
    replies drift to random subjects. This fixed-size representation adds
    five anchored question tokens alongside eleven recent answer tokens.
    """
    try:
        answer_start=len(prefix)-1-prefix[::-1].index(4)
        user_start=max(i for i in range(answer_start) if prefix[i]==3)
        question=prefix[user_start+1:answer_start]
    except (ValueError, IndexError):
        question=[]
    if question:
        # Evenly sample question tokens, including its beginning and end.
        anchors=[3]+[question[round(i*(len(question)-1)/3)] for i in range(4)]
    else:
        anchors=[3,0,0,0,0]
    recent=([0]*11+prefix[-11:])[-11:]
    return anchors+recent


def _sparse_add(np, table, row_ids, row_grads):
    """Vectorized sum of repeated sparse embedding gradients (faster than np.add.at)."""
    order = np.argsort(row_ids,kind='stable')
    sorted_ids = row_ids[order]
    start = np.concatenate((np.array([0],dtype=np.int64),
                            np.nonzero(sorted_ids[1:]!=sorted_ids[:-1])[0]+1))
    grouped_grads = np.add.reduceat(row_grads[order],start,axis=0)
    table[sorted_ids[start]] += grouped_grads



def _trf_layer_norm(np, x, gamma, beta):
    mean = x.mean(axis=-1, keepdims=True)
    centered = x - mean
    inv_std = 1.0 / np.sqrt((centered * centered).mean(axis=-1, keepdims=True) + 1e-5)
    normalized = centered * inv_std
    return normalized * gamma + beta, (normalized, inv_std)


def _trf_layer_norm_backward(np, grad, cache, gamma):
    normalized, inv_std = cache
    axes = tuple(range(grad.ndim - 1))
    d_gamma = (grad * normalized).sum(axis=axes)
    d_beta = grad.sum(axis=axes)
    d_norm = grad * gamma
    width = grad.shape[-1]
    d_x = (inv_std / width) * (
        width * d_norm
        - d_norm.sum(axis=-1, keepdims=True)
        - normalized * (d_norm * normalized).sum(axis=-1, keepdims=True)
    )
    return d_x, d_gamma, d_beta


def _trf_parameter_names():
    names = ['tok_emb', 'pos_emb', 'final_ln_g', 'final_ln_b']
    for layer in range(TRANSFORMER_LAYERS):
        p = f'layer{layer}_'
        names.extend(p + name for name in (
            'ln1_g', 'ln1_b', 'wq', 'wk', 'wv', 'wo',
            'ln2_g', 'ln2_b', 'w1', 'b1', 'w2', 'b2'
        ))
    return names


def _trf_initialize(np):
    rng = np.random.default_rng(20261114)
    d, f = TRANSFORMER_DIM, TRANSFORMER_FF
    params = {
        'tok_emb': rng.normal(0.0, 0.02, (VOCAB_SIZE, d)).astype('float32'),
        'pos_emb': rng.normal(0.0, 0.01, (TRANSFORMER_CONTEXT, d)).astype('float32'),
        'final_ln_g': np.ones((d,), dtype='float32'),
        'final_ln_b': np.zeros((d,), dtype='float32'),
    }
    for layer in range(TRANSFORMER_LAYERS):
        p = f'layer{layer}_'
        params[p + 'ln1_g'] = np.ones((d,), dtype='float32')
        params[p + 'ln1_b'] = np.zeros((d,), dtype='float32')
        params[p + 'ln2_g'] = np.ones((d,), dtype='float32')
        params[p + 'ln2_b'] = np.zeros((d,), dtype='float32')
        for name in ('wq', 'wk', 'wv', 'wo'):
            params[p + name] = rng.normal(0.0, 1.0 / math.sqrt(d), (d, d)).astype('float32')
        params[p + 'w1'] = rng.normal(0.0, math.sqrt(2.0 / d), (d, f)).astype('float32')
        params[p + 'b1'] = np.zeros((f,), dtype='float32')
        params[p + 'w2'] = rng.normal(0.0, math.sqrt(2.0 / f), (f, d)).astype('float32')
        params[p + 'b2'] = np.zeros((d,), dtype='float32')
    return params


def save_transformer(db, np, params, moment1, moment2, step):
    """Persist Transformer parameters AND Adam state in BRAIN.db."""
    enforce_db_size(db, 80 * 1024 * 1024)
    for prefix, collection in (
        ('trf_p_', params), ('trf_m_', moment1), ('trf_v_', moment2)
    ):
        for name, array in collection.items():
            if name.startswith('_'):
                continue
            # CUDA arrays are copied to host for the portable SQLite checkpoint.
            # CPU/GPU checkpoints share identical float32 serialization.
            host_array = array.get() if hasattr(array, 'get') else array
            payload = zlib.compress(
                ensure_numpy().asarray(host_array, dtype='<f4').tobytes(), 1
            )
            db.execute(
                'INSERT OR REPLACE INTO weights(key,value) VALUES(?,?)',
                (prefix + name, sqlite3.Binary(payload))
            )
    set_meta(db, 'transformer_version', TRANSFORMER_VERSION)
    set_meta(db, 'transformer_config', json.dumps(TRANSFORMER_CONFIG, sort_keys=True))
    set_meta(db, 'transformer_steps', int(step))
    set_meta(db, 'student_steps', int(step))
    db.commit()


def load_transformer(db, np, vocab=None):
    """Load the causal Transformer; initialize it once if no compatible checkpoint exists."""
    vocab = vocab or build_vocabulary(db)
    names = _trf_parameter_names()
    version_ok = get_meta(db, 'transformer_version') == TRANSFORMER_VERSION
    params, moment1, moment2 = {}, {}, {}
    # Build expected shapes locally instead of relying on a module-level alias.
    # This also makes checkpoint loading robust to stale/renamed shape globals.
    expected_shapes = _trf_shapes()
    if version_ok:
        try:
            for prefix, target in (
                ('trf_p_', params), ('trf_m_', moment1), ('trf_v_', moment2)
            ):
                for name in names:
                    row = db.execute(
                        'SELECT value FROM weights WHERE key=?', (prefix + name,)
                    ).fetchone()
                    if not row:
                        raise KeyError(prefix + name)
                    array = np.frombuffer(
                        zlib.decompress(row[0]), dtype='<f4'
                    ).copy()
                    target[name] = array.reshape(expected_shapes[name])
        except (KeyError, ValueError, zlib.error):
            version_ok = False
    if not version_ok:
        # Preserve the previous architecture checkpoint before starting the BPE model.
        old_rows = db.execute("SELECT key,value FROM weights WHERE key GLOB 'trf_*'").fetchall()
        for old_key, old_value in old_rows:
            db.execute(
                'INSERT OR IGNORE INTO weights(key,value) VALUES(?,?)',
                ('legacy_v1_' + old_key, old_value)
            )
            db.execute('DELETE FROM weights WHERE key=?', (old_key,))
        params = _trf_initialize(np)
        moment1 = {name: np.zeros_like(value) for name, value in params.items()}
        moment2 = {name: np.zeros_like(value) for name, value in params.items()}
        step = 0
        save_transformer(db, np, params, moment1, moment2, step)
        say(
            f'Initialized causal Transformer: {PARAMETERS:,} parameters, '
            f'{TRANSFORMER_LAYERS} layers, {TRANSFORMER_HEADS} attention heads, '
            f'{TRANSFORMER_CONTEXT}-token context.'
        )
    else:
        step = int(get_meta(db, 'transformer_steps', 0))
    return params, moment1, moment2, step


def _trf_shapes():
    d, f = TRANSFORMER_DIM, TRANSFORMER_FF
    shapes = {
        'tok_emb': (VOCAB_SIZE, d),
        'pos_emb': (TRANSFORMER_CONTEXT, d),
        'final_ln_g': (d,), 'final_ln_b': (d,),
    }
    for layer in range(TRANSFORMER_LAYERS):
        p = f'layer{layer}_'
        shapes.update({
            p + 'ln1_g': (d,), p + 'ln1_b': (d,),
            p + 'ln2_g': (d,), p + 'ln2_b': (d,),
            p + 'wq': (d, d), p + 'wk': (d, d),
            p + 'wv': (d, d), p + 'wo': (d, d),
            p + 'w1': (d, f), p + 'b1': (f,),
            p + 'w2': (f, d), p + 'b2': (d,),
        })
    return shapes


_trf_initialize_shapes = _trf_shapes()


def transformer_forward(np, params, token_ids):
    """Causal self-attention forward pass. token_ids has shape [batch, time]."""
    ids = np.asarray(token_ids, dtype=np.int32)
    if ids.ndim == 1:
        ids = ids[None, :]
    batch, time = ids.shape
    if time > TRANSFORMER_CONTEXT:
        ids = ids[:, -TRANSFORMER_CONTEXT:]
        time = ids.shape[1]
    d, heads = TRANSFORMER_DIM, TRANSFORMER_HEADS
    head_dim = d // heads
    x = params['tok_emb'][ids] + params['pos_emb'][None, :time, :]
    block_caches = []
    causal = np.triu(np.ones((time, time), dtype=bool), k=1)[None, None, :, :]

    for layer in range(TRANSFORMER_LAYERS):
        p = f'layer{layer}_'
        n1, ln1_cache = _trf_layer_norm(
            np, x, params[p + 'ln1_g'], params[p + 'ln1_b']
        )
        q = (n1 @ params[p + 'wq']).reshape(batch, time, heads, head_dim).transpose(0, 2, 1, 3)
        k = (n1 @ params[p + 'wk']).reshape(batch, time, heads, head_dim).transpose(0, 2, 1, 3)
        v = (n1 @ params[p + 'wv']).reshape(batch, time, heads, head_dim).transpose(0, 2, 1, 3)
        scores = (q @ np.swapaxes(k, -1, -2)) / math.sqrt(head_dim)
        scores = np.where(causal, -1e9, scores)
        scores = scores - scores.max(axis=-1, keepdims=True)
        attention = np.exp(scores)
        attention /= np.maximum(attention.sum(axis=-1, keepdims=True), 1e-12)
        context = attention @ v
        merged = context.transpose(0, 2, 1, 3).reshape(batch, time, d)
        attended = merged @ params[p + 'wo']
        x1 = x + attended

        n2, ln2_cache = _trf_layer_norm(
            np, x1, params[p + 'ln2_g'], params[p + 'ln2_b']
        )
        pre = n2 @ params[p + 'w1'] + params[p + 'b1']
        activation = np.maximum(pre, 0.0)
        ff_out = activation @ params[p + 'w2'] + params[p + 'b2']
        x2 = x1 + ff_out
        block_caches.append({
            'ln1': ln1_cache, 'n1': n1, 'q': q, 'k': k, 'v': v,
            'attention': attention, 'merged': merged, 'ln2': ln2_cache,
            'n2': n2, 'pre': pre, 'activation': activation,
        })
        x = x2

    final, final_cache = _trf_layer_norm(
        np, x, params['final_ln_g'], params['final_ln_b']
    )
    # Tied input/output token embeddings.
    active_vocab = int(params.get('_active_vocab', VOCAB_SIZE))
    logits = final @ params['tok_emb'][:active_vocab].T
    cache = {
        'ids': ids, 'blocks': block_caches, 'final': final,
        'final_ln': final_cache, 'active_vocab': logits.shape[-1],
    }
    return logits, cache


def vocab_for_forward(params):
    # All unused capacity rows are masked at generation/training call sites.
    # The active vocabulary length is attached transiently by the trainer.
    return range(int(params.get('_active_vocab', VOCAB_SIZE)))


def _trf_backward(np, params, cache, dlogits):
    """Backpropagate full-vocabulary cross entropy through attention and FFN blocks."""
    ids = cache['ids']
    batch, time = ids.shape
    d, heads = TRANSFORMER_DIM, TRANSFORMER_HEADS
    head_dim = d // heads
    active = cache['active_vocab']
    final = cache['final']
    grads = {name: np.zeros_like(value) for name, value in params.items() if not name.startswith('_')}
    d_embedding = np.zeros_like(params['tok_emb'])

    grads['tok_emb'][:active] = (
        dlogits.reshape(-1, active).T @ final.reshape(-1, d)
    )
    d_final = dlogits @ params['tok_emb'][:active]
    dx, grads['final_ln_g'], grads['final_ln_b'] = _trf_layer_norm_backward(
        np, d_final, cache['final_ln'], params['final_ln_g']
    )

    for layer in reversed(range(TRANSFORMER_LAYERS)):
        p = f'layer{layer}_'
        c = cache['blocks'][layer]
        # x2 = x1 + FF(LN(x1))
        d_x1 = dx.copy()
        d_ff = dx
        grads[p + 'w2'] = c['activation'].reshape(-1, TRANSFORMER_FF).T @ d_ff.reshape(-1, d)
        grads[p + 'b2'] = d_ff.sum(axis=(0, 1))
        d_activation = d_ff @ params[p + 'w2'].T
        d_pre = d_activation * (c['pre'] > 0.0)
        grads[p + 'w1'] = c['n2'].reshape(-1, d).T @ d_pre.reshape(-1, TRANSFORMER_FF)
        grads[p + 'b1'] = d_pre.sum(axis=(0, 1))
        d_n2 = d_pre @ params[p + 'w1'].T
        d_ln2, grads[p + 'ln2_g'], grads[p + 'ln2_b'] = _trf_layer_norm_backward(
            np, d_n2, c['ln2'], params[p + 'ln2_g']
        )
        d_x1 += d_ln2

        # x1 = x + attention(LN(x))
        d_x = d_x1.copy()
        d_merged = d_x1 @ params[p + 'wo'].T
        grads[p + 'wo'] = c['merged'].reshape(-1, d).T @ d_x1.reshape(-1, d)
        d_context = d_merged.reshape(batch, time, heads, head_dim).transpose(0, 2, 1, 3)
        attention = c['attention']
        v = c['v']
        d_attention = d_context @ np.swapaxes(v, -1, -2)
        d_v = np.swapaxes(attention, -1, -2) @ d_context
        d_scores = attention * (
            d_attention - (d_attention * attention).sum(axis=-1, keepdims=True)
        )
        causal = np.triu(np.ones((time, time), dtype=bool), k=1)[None, None, :, :]
        d_scores = np.where(causal, 0.0, d_scores)
        q, k = c['q'], c['k']
        d_q = (d_scores @ k) / math.sqrt(head_dim)
        d_k = (np.swapaxes(d_scores, -1, -2) @ q) / math.sqrt(head_dim)

        dq_flat = d_q.transpose(0, 2, 1, 3).reshape(batch, time, d)
        dk_flat = d_k.transpose(0, 2, 1, 3).reshape(batch, time, d)
        dv_flat = d_v.transpose(0, 2, 1, 3).reshape(batch, time, d)
        n1 = c['n1']
        grads[p + 'wq'] = n1.reshape(-1, d).T @ dq_flat.reshape(-1, d)
        grads[p + 'wk'] = n1.reshape(-1, d).T @ dk_flat.reshape(-1, d)
        grads[p + 'wv'] = n1.reshape(-1, d).T @ dv_flat.reshape(-1, d)
        d_n1 = (
            dq_flat @ params[p + 'wq'].T
            + dk_flat @ params[p + 'wk'].T
            + dv_flat @ params[p + 'wv'].T
        )
        d_ln1, grads[p + 'ln1_g'], grads[p + 'ln1_b'] = _trf_layer_norm_backward(
            np, d_n1, c['ln1'], params[p + 'ln1_g']
        )
        dx = d_x + d_ln1

    np.add.at(d_embedding, ids.reshape(-1), dx.reshape(-1, d))
    grads['tok_emb'] += d_embedding
    grads['pos_emb'] = np.zeros_like(params['pos_emb'])
    grads['pos_emb'][:time] = dx.sum(axis=0)
    return grads


def _trf_make_batch(np, examples, lookup):
    encoded = []
    for question, answer in examples:
        q = tokenizer(question)[-96:]
        a = tokenizer(answer)
        max_answer = max(1, TRANSFORMER_CONTEXT - len(q) - 2)
        a = a[:max_answer]
        if not q and not a:
            continue
        q_ids = [lookup.get(token, 1) for token in q]
        a_ids = [lookup.get(token, 1) for token in a]
        sequence = [3] + q_ids + [4] + a_ids + [2]
        x, y = sequence[:-1], sequence[1:]
        mask = [0.0] * len(y)
        answer_start = len(q_ids) + 1
        for index in range(answer_start, len(y)):
            mask[index] = 1.0
        if any(mask):
            encoded.append((x, y, mask))
    if not encoded:
        return None
    time_steps = max(len(item[0]) for item in encoded)
    batch = len(encoded)
    x_ids = np.zeros((batch, time_steps), dtype=np.int32)
    targets = np.zeros((batch, time_steps), dtype=np.int32)
    loss_mask = np.zeros((batch, time_steps), dtype=np.float32)
    for row, (x, y, mask) in enumerate(encoded):
        x_ids[row, :len(x)] = x
        targets[row, :len(y)] = y
        loss_mask[row, :len(mask)] = mask
    return x_ids, targets, loss_mask


def _trf_loss(np, params, x_ids, targets, loss_mask, backward=False):
    # Only the currently known vocabulary participates in the softmax.
    active = int(params['_active_vocab'])
    logits, cache = transformer_forward(np, params, x_ids)
    logits = logits.astype('float32', copy=False)
    shifted = logits - logits.max(axis=-1, keepdims=True)
    exp_scores = np.exp(np.clip(shifted, -60.0, 0.0))
    probabilities = exp_scores / np.maximum(exp_scores.sum(axis=-1, keepdims=True), 1e-12)
    b_idx, t_idx = np.indices(targets.shape)
    chosen = probabilities[b_idx, t_idx, targets]
    denominator = max(float(loss_mask.sum()), 1.0)
    loss = float(-(np.log(np.maximum(chosen, 1e-12)) * loss_mask).sum() / denominator)
    if not backward:
        return loss, None
    probabilities[b_idx, t_idx, targets] -= 1.0
    probabilities *= (loss_mask / denominator)[..., None]
    gradients = _trf_backward(np, params, cache, probabilities)
    return loss, gradients


def transformer_validation_loss(db, np, params, vocab, limit=40):
    """Held-out loss on every tenth saved lesson; no gradient updates."""
    rows = db.execute(
        "SELECT prompt,answer FROM lessons "
        "WHERE id % 10 = 0 AND origin IN ('seed','user','teacher','dialogue_quality_v5') "
        "ORDER BY id DESC LIMIT ?", (max(1, int(limit)),)
    ).fetchall()
    if not rows:
        return None
    lookup = {word: index for index, word in enumerate(vocab)}
    losses = []
    for start in range(0, len(rows), TRANSFORMER_BATCH):
        batch = _trf_make_batch(np, rows[start:start + TRANSFORMER_BATCH], lookup)
        if batch is None:
            continue
        loss, _ = _trf_loss(np, params, *batch, backward=False)
        losses.append(loss)
    return float(sum(losses) / len(losses)) if losses else None


def train_student(db, np, rows, max_steps=2000, print_every=100,
                  device='auto', resource_profile='balanced'):
    """CPU-prepared batches, adaptive throttling, optional CUDA/CuPy gradients.

    In GPU mode, tokenization and SQLite remain on CPU, while the actual
    Transformer forward/backward/Adam math runs on NVIDIA CUDA.
    NumPy remains the reliable fallback and no downloads occur here.
    """
    cpu_np = ensure_numpy(resource_profile)
    governor = AdaptiveResources(resource_profile)
    xp = governor.choose_backend(device) or cpu_np
    gpu = xp is not cpu_np

    vocab = build_vocabulary(db)
    lookup = {word: index for index, word in enumerate(vocab)}
    params, moment1, moment2, total_steps = load_transformer(db, cpu_np, vocab)
    if gpu:
        params = {name: xp.asarray(value) for name, value in params.items()}
        moment1 = {name: xp.asarray(value) for name, value in moment1.items()}
        moment2 = {name: xp.asarray(value) for name, value in moment2.items()}
        say('Backend: NVIDIA CUDA / CuPy (CPU handles tokenization, validation data and SQLite).')
    else:
        say('Backend: NumPy CPU (CuPy is optional and was not loaded).')
    say('Adaptive resources: ' + governor.describe())
    params['_active_vocab'] = len(vocab)
    batch_count = 0
    last_loss = 0.0
    started = time.monotonic()
    print_every = max(1, int(print_every))

    # Bounded CPU producer: prepares the next batch while GPU/CPU optimizes
    # the current batch. Maximum two waiting batches limits additional RAM.
    prepared = queue.Queue(maxsize=8 if resource_profile == 'max' else 2)
    stop_prefetch = threading.Event()

    def prefetch():
        pending = []
        try:
            for question, answer in rows:
                if stop_prefetch.is_set():
                    break
                if not question.strip() or not answer.strip():
                    continue
                pending.append((question, answer))
                if len(pending) < TRANSFORMER_BATCH:
                    continue
                batch = _trf_make_batch(cpu_np, pending, lookup)
                pending.clear()
                if batch is not None:
                    while not stop_prefetch.is_set():
                        try:
                            prepared.put(batch, timeout=0.2)
                            break
                        except queue.Full:
                            continue
            if pending and not stop_prefetch.is_set():
                batch = _trf_make_batch(cpu_np, pending, lookup)
                if batch is not None:
                    while not stop_prefetch.is_set():
                        try:
                            prepared.put(batch, timeout=0.2)
                            break
                        except queue.Full:
                            continue
        except Exception as exc:
            while not stop_prefetch.is_set():
                try:
                    prepared.put(exc, timeout=0.2)
                    break
                except queue.Full:
                    continue
        finally:
            while not stop_prefetch.is_set():
                try:
                    prepared.put(None, timeout=0.2)
                    break
                except queue.Full:
                    continue

    feeder = threading.Thread(target=prefetch, daemon=True, name='axon_cpu_tokenizer')
    feeder.start()

    def update(batch):
        nonlocal batch_count, total_steps, last_loss
        governor.throttle()
        if gpu:
            batch = tuple(xp.asarray(item) for item in batch)
        last_loss, gradients = _trf_loss(xp, params, *batch, backward=True)
        # GPU: reduce all gradient norms on-device and synchronize once.
        norm_sq = float(sum((grad * grad).sum() for grad in gradients.values()))
        grad_scale = min(1.0, 1.0 / max(math.sqrt(norm_sq), 1e-8))
        total_steps += 1
        lr = 0.00045 * min(1.0, total_steps / 12.0) / math.sqrt(1.0 + total_steps / 5000.0)
        beta1, beta2 = 0.9, 0.999
        correction1 = 1.0 - beta1 ** total_steps
        correction2 = 1.0 - beta2 ** total_steps
        for name, grad in gradients.items():
            grad = grad * grad_scale
            moment1[name] *= beta1
            moment1[name] += (1.0 - beta1) * grad
            moment2[name] *= beta2
            moment2[name] += (1.0 - beta2) * (grad * grad)
            m_hat = moment1[name] / correction1
            v_hat = moment2[name] / correction2
            params[name] -= lr * m_hat / (xp.sqrt(v_hat) + 1e-8)
            if name.endswith(('wq', 'wk', 'wv', 'wo', 'w1', 'w2')):
                params[name] *= (1.0 - lr * 0.01)
        batch_count += 1

    try:
        while max_steps is None or batch_count < int(max_steps):
            item = prepared.get()
            if item is None:
                break
            if isinstance(item, Exception):
                raise item
            update(item)
            if batch_count and batch_count % print_every == 0:
                save_transformer(db, cpu_np, params, moment1, moment2, total_steps)
                # Small validation sample avoids long foreground stalls.
                val = transformer_validation_loss(
                    db, xp, params, vocab, limit=16
                )
                set_meta(
                    db, 'transformer_validation_loss',
                    'n/a' if val is None else f'{val:.5f}'
                )
                db.commit()
                elapsed = max(time.monotonic() - started, 0.001)
                val_text = 'n/a' if val is None else f'{val:.3f}'
                say(
                    f'Transformer batch {batch_count:,}'
                    + (f'/{max_steps:,}' if max_steps is not None else '')
                    + f' | train loss {last_loss:.3f} | validation loss {val_text}'
                    + f' | {elapsed:.1f}s | {"CUDA" if gpu else "CPU"}'
                    + f' | {governor.describe()}'
                )
    except KeyboardInterrupt:
        say('\nInterrupted: saving Transformer weights and Adam state...')
        save_transformer(db, cpu_np, params, moment1, moment2, total_steps)
        raise
    finally:
        stop_prefetch.set()
        feeder.join(timeout=1.0)

    save_transformer(db, cpu_np, params, moment1, moment2, total_steps)
    val = transformer_validation_loss(db, xp, params, vocab, limit=32)
    set_meta(db, 'transformer_validation_loss', 'n/a' if val is None else f'{val:.5f}')
    set_meta(db, 'transformer_last_train_loss', f'{last_loss:.5f}')
    db.commit()
    say(
        f'Transformer trained {batch_count:,} batches; total {total_steps:,}. '
        f'Final train loss {last_loss:.3f}; validation loss '
        + ('n/a (need held-out lessons)' if val is None else f'{val:.3f}')
    )
    return batch_count


def _format_piece(token, previous):
    """Convert one BPE token to a streaming text fragment."""
    has_space = token.startswith('▁')
    text = token[1:] if has_space else token
    if not text:
        return ''
    if text in ('.', ',', '!', '?', ':', ';', '%', ')', ']', '}'):
        return text
    if text in ('(', '[', '{'):
        return text
    if not previous:
        return text[0].upper() + text[1:]
    return (' ' if has_space else '') + text


def transformer_generate(db, prompt, length=MAX_GENERATION_TOKENS,
                         temperature=GENERATION_TEMPERATURE, top_k=GENERATION_TOP_K,
                         top_p=GENERATION_TOP_P, on_piece=None, history=None):
    """Generate every reply with AXON's own causal Transformer, one BPE token at a time."""
    np = ensure_numpy()
    vocab = build_vocabulary(db)
    vocab = extend_vocabulary(db, prompt)
    if int(get_meta(db, 'transformer_steps', 0)) <= 0:
        return '[AXON Transformer has not been trained yet. Run LLM Train.py first.]'
    params, _, _, _ = load_transformer(db, np, vocab)
    params['_active_vocab'] = len(vocab)
    lookup = {token: index for index, token in enumerate(vocab)}

    # Recent turns are prompt context only; no saved answer is retrieved.
    context_tokens = []
    if history:
        for old_question, old_answer in history[-6:]:
            context_tokens.extend(
                [3] + [lookup.get(token, 1) for token in tokenizer(old_question)]
                + [4] + [lookup.get(token, 1) for token in tokenizer(old_answer)] + [2]
            )
    context_tokens.extend(
        [3] + [lookup.get(token, 1) for token in tokenizer(prompt)] + [4]
    )
    context_tokens = context_tokens[-TRANSFORMER_CONTEXT:]
    if context_tokens and context_tokens[0] != 3:
        context_tokens = [3] + context_tokens[-(TRANSFORMER_CONTEXT - 1):]

    generated = []
    output = []
    previous_text = ''
    rng = np.random.default_rng()
    max_new = max(1, min(MAX_GENERATION_TOKENS, int(length)))
    temperature = max(0.15, min(1.5, float(temperature)))
    top_k = max(2, min(int(top_k), len(vocab)))

    for step in range(max_new):
        token_ids = np.asarray(
            [context_tokens[-TRANSFORMER_CONTEXT:]], dtype=np.int32
        )
        logits, _ = transformer_forward(np, params, token_ids)
        scores = logits[0, -1, :len(vocab)].astype('float64', copy=True)
        scores[0] = -1e9  # pad
        scores[1] = -1e9  # unknown
        scores[3] = -1e9  # user marker
        scores[4] = -1e9  # assistant marker
        if step < 8:
            scores[2] = -1e9  # minimum continuation

        recent_counts = collections.Counter(generated[-96:])
        for token_id, count in recent_counts.items():
            if token_id >= len(SPECIAL):
                scores[token_id] -= 0.65 * min(count, 4)

        # Prevent a repeated four-token continuation when the same prefix returns.
        if len(generated) >= 3:
            prefix = tuple(generated[-3:])
            for index in range(len(generated) - 3):
                if tuple(generated[index:index + 3]) == prefix:
                    scores[generated[index + 3]] = -1e9

        if generated:
            last_token = vocab[generated[-1]]
            last_text = last_token[1:] if last_token.startswith('▁') else last_token
            if last_text in ('.', ',', '!', '?', ':', ';'):
                for punctuation in ('.', ',', '!', '?', ':', ';'):
                    punctuation_id = lookup.get('▁' + punctuation)
                    if punctuation_id is not None:
                        scores[punctuation_id] = -1e9

        candidates = np.argpartition(scores, -top_k)[-top_k:]
        candidate_scores = scores[candidates] / temperature
        candidate_scores -= candidate_scores.max()
        probabilities = np.exp(np.clip(candidate_scores, -60.0, 0.0))
        probabilities /= max(float(probabilities.sum()), 1e-12)
        order = np.argsort(-probabilities)
        candidates = candidates[order]
        probabilities = probabilities[order]

        # Nucleus sampling with a minimum-probability filter.
        keep = probabilities >= probabilities[0] * 0.03
        candidates = candidates[keep]
        probabilities = probabilities[keep]
        cumulative = np.cumsum(probabilities)
        nucleus = cumulative - probabilities < max(0.05, min(1.0, float(top_p)))
        nucleus[0] = True
        candidates = candidates[nucleus]
        probabilities = probabilities[nucleus]
        probabilities /= probabilities.sum()

        # Deliberate next-token search: choose among several plausible first
        # tokens by asking AXON's OWN neural weights how well each can continue.
        # No teacher model, retrieval, hardcoded replies or external AI calls.
        # A single batched forward pass evaluates all speculative branches.
        branch_count = min(GENERATION_LOOKAHEAD_BRANCHES, len(candidates))
        if branch_count > 1:
            branch_ids = candidates[:branch_count]
            # All branches have the same number of context tokens.
            branch_contexts = np.asarray([
                (context_tokens + [int(token_id)])[-TRANSFORMER_CONTEXT:]
                for token_id in branch_ids
            ], dtype=np.int32)
            future_logits, _ = transformer_forward(np, params, branch_contexts)
            future_scores = future_logits[:, -1, :len(vocab)].astype('float64')
            future_scores[:, 0] = -1e9  # pad
            future_scores[:, 1] = -1e9  # unknown
            future_scores[:, 3] = -1e9  # role marker
            future_scores[:, 4] = -1e9  # role marker
            if step < 7:
                future_scores[:, 2] = -1e9  # avoid abrupt beginnings

            # The best possible follow-up token probability is a bounded
            # coherence proxy, NOT human-like reasoning or an answer checker.
            scaled_future = future_scores / temperature
            max_future = scaled_future.max(axis=1)
            shifted_future = scaled_future - max_future[:, None]
            future_log_norm = np.log(
                np.maximum(
                    np.exp(np.clip(shifted_future, -80.0, 0.0)).sum(axis=1),
                    1e-12
                )
            )
            # A coherent continuation should be plausible *and* predictable.
            # Keep the original next-token probabilities as the main signal.
            branch_log_weight = (
                np.log(np.maximum(probabilities[:branch_count], 1e-12))
                - GENERATION_LOOKAHEAD_WEIGHT * future_log_norm
            )
            branch_log_weight -= branch_log_weight.max()
            branch_weights = np.exp(branch_log_weight)
            branch_weights /= np.maximum(branch_weights.sum(), 1e-12)
            choice = int(rng.choice(branch_ids, p=branch_weights))
        else:
            choice = int(rng.choice(candidates, p=probabilities))
        if choice == 2:
            break

        token = vocab[choice]
        piece = _format_piece(token, previous_text)
        output.append(piece)
        if piece:
            if on_piece is not None:
                on_piece(piece)
            if token.startswith('▁'):
                previous_text = token[1:] or previous_text
            else:
                previous_text += token
        context_tokens.append(choice)
        generated.append(choice)

        if len(generated) >= 32 and generated[-8:] == generated[-16:-8]:
            break

    return ''.join(output)


def student_generate(db, prompt, length=MAX_GENERATION_TOKENS, temperature=GENERATION_TEMPERATURE, top_k=GENERATION_TOP_K,
                     on_piece=None, state=None, history=None):
    """Compatibility wrapper used by MANUAL Chat.py; runs the causal Transformer."""
    return transformer_generate(
        db, prompt, length=length, temperature=temperature, top_k=top_k,
        on_piece=on_piece, history=history
    )



